var b=html.indexOf('</div>{697}',a);
var body=a>=0&&b>a?html.substring(a+18,b):'';
var ps=body.split('<p>');
var out=[];
for(var i=1;
i<ps.length;
i++){var t=ps[i].split('</p>')[0].replaceAll('<[^>]+>','').trim();
